<?php
require_once __DIR__.'/includes/bootstrap.php'; if(is_logged_in())redirect('dashboard.php');
$errors=[];$name=$email=$phone='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['full_name']??'');$email=strtolower(trim($_POST['email']??''));$phone=trim($_POST['phone']??'');$p=$_POST['password']??'';$c=$_POST['confirm_password']??'';
if(!valid_name($name))$errors[]='Enter a name between 2 and 100 characters.';if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email.';if($phone!==''&&!preg_match('/^[0-9+() .-]{7,20}$/',$phone))$errors[]='Enter a valid phone number.';if(!strong_password($p))$errors[]='Password needs 8+ characters, letters, and numbers.';if($p!==$c)$errors[]='Passwords do not match.';
if(!$errors){$s=db()->prepare('SELECT id FROM users WHERE email=?');$s->execute([$email]);if($s->fetch())$errors[]='Email already registered.';else{$s=db()->prepare('INSERT INTO users(full_name,email,phone,password_hash,role) VALUES(?,?,?,?,"user")');$s->execute([$name,$email,$phone?:null,password_hash($p,PASSWORD_DEFAULT)]);set_flash('success','Account created. You can now log in.');redirect('login.php');}}}
render_header('Register'); ?>
<section class="auth"><div class="intro"><p class="eyebrow">GET STARTED</p><h1>Create your account.</h1><p>Secure registration and simple profile management in one responsive workspace.</p><p>✓ Hashed passwords<br>✓ Validated inputs<br>✓ User profile controls</p></div><section class="panel"><h2>Registration</h2><?php if($errors):?><div class="alert error"><?php foreach($errors as $x)echo '<p>'.e($x).'</p>';?></div><?php endif;?>
<form method="post" class="form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>Full name *<input name="full_name" required maxlength="100" value="<?=e($name)?>"></label><label>Email *<input type="email" name="email" required value="<?=e($email)?>"></label><label>Phone<input name="phone" value="<?=e($phone)?>"></label><label>Password *<div class="pw"><input id="pw" type="password" name="password" required><button type="button" data-show="pw">Show</button></div><small id="strength"></small></label><label>Confirm password *<div class="pw"><input id="confirm" type="password" name="confirm_password" required><button type="button" data-show="confirm">Show</button></div><small id="match"></small></label><button class="btn">Create account →</button></form><p class="center">Already registered? <a href="<?=e(BASE_URL)?>/login.php">Log in</a></p></section></section><?php render_footer(); ?>
